package com.crypto.laplace.stop; import lombok.RequiredArgsConstructor; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor @ConditionalOnProperty(prefix="trading.laplace",name="enabled",havingValue="true") public class LaplaceFiveMinuteStopScheduler { private final LaplaceFiveMinuteStopService service; @Scheduled(cron="${trading.laplace.stop-cron}",zone="${trading.laplace.stop-zone}") public void run(){service.checkOpenPositions();} }
